export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export function parseFrontmatter(content: string): { data: Frontmatter; content: string } {
  const lines = content.split('\n');

  if (!lines[0].startsWith('---')) {
    return { data: {}, content };
  }

  let endIndex = -1;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].startsWith('---')) {
      endIndex = i;
      break;
    }
  }

  if (endIndex === -1) {
    return { data: {}, content };
  }

  const frontmatterBlock = lines.slice(1, endIndex).join('\n');
  const markdownContent = lines.slice(endIndex + 1).join('\n');

  const data = parseYAML(frontmatterBlock);

  return { data, content: markdownContent };
}

function parseYAML(yamlStr: string): Frontmatter {
  const data: Frontmatter = {};

  if (!yamlStr.trim()) {
    return data;
  }

  const lines = yamlStr.split('\n');
  for (const line of lines) {
    if (!line.trim() || line.trim().startsWith('#')) {
      continue;
    }

    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) {
      continue;
    }

    const key = line.substring(0, colonIndex).trim();
    let value = line.substring(colonIndex + 1).trim();

    if (value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1);
    } else if (value.startsWith("'") && value.endsWith("'")) {
      value = value.slice(1, -1);
    } else if (value === 'true') {
      data[key] = true;
      continue;
    } else if (value === 'false') {
      data[key] = false;
      continue;
    } else if (value.startsWith('[') && value.endsWith(']')) {
      const arrayStr = value.slice(1, -1);
      data[key] = arrayStr.split(',').map(item => item.trim());
      continue;
    }

    data[key] = value;
  }

  return data;
}

import { marked } from 'marked';

export async function markdownToHtml(markdown: string): Promise<string> {
  return await marked(markdown);
}

import { promises as fs } from 'fs';
import path from 'path';

export interface MarkdownFile {
  name: string;
  path: string;
  content: string;
}

export async function readMarkdownFiles(contentDir: string): Promise<MarkdownFile[]> {
  const files: MarkdownFile[] = [];

  try {
    const entries = await fs.readdir(contentDir);
    for (const entry of entries) {
      if (entry.endsWith('.md')) {
        const filePath = path.join(contentDir, entry);
        const content = await fs.readFile(filePath, 'utf-8');
        files.push({
          name: entry,
          path: filePath,
          content
        });
      }
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      await fs.mkdir(contentDir, { recursive: true });
    } else {
      throw error;
    }
  }

  return files;
}

export async function writeFile(filePath: string, content: string): Promise<void> {
  const dir = path.dirname(filePath);
  await fs.mkdir(dir, { recursive: true });
  await fs.writeFile(filePath, content, 'utf-8');
}

export async function ensureDir(dirPath: string): Promise<void> {
  await fs.mkdir(dirPath, { recursive: true });
}

import { parseFrontmatter, Frontmatter } from './frontmatter';
import { markdownToHtml } from './markdown';

export interface PageData {
  title: string;
  date?: string;
  tags?: string[];
  html: string;
  slug: string;
  [key: string]: unknown;
}

export async function processMarkdownFile(filename: string, content: string): Promise<PageData> {
  const { data, content: markdownContent } = parseFrontmatter(content);
  const html = await markdownToHtml(markdownContent);
  const slug = filename.replace(/\.md$/, '');

  const title = (data.title as string) || slug.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');

  return {
    slug,
    title,
    date: data.date as string | undefined,
    tags: Array.isArray(data.tags) ? data.tags : undefined,
    html,
    ...data
  };
}

import path from 'path';
import { writeFile } from './files';
import { PageData } from './page';

export async function generatePageHtml(page: PageData, outputDir: string): Promise<void> {
  const html = createPageHtml(page);
  const filePath = path.join(outputDir, `${page.slug}.html`);
  await writeFile(filePath, html);
}

export async function generateIndexHtml(pages: PageData[], outputDir: string): Promise<void> {
  const html = createIndexHtml(pages);
  const filePath = path.join(outputDir, 'index.html');
  await writeFile(filePath, html);
}

function createPageHtml(page: PageData): string {
  const tagsList = page.tags && Array.isArray(page.tags)
    ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>`
    : '';

  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(page.title)}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
    h1 { color: #000; margin-bottom: 10px; }
    .meta { color: #666; margin-bottom: 20px; border-bottom: 1px solid #eee; padding-bottom: 10px; }
    .date { margin: 0; font-size: 0.9em; }
    .tags { margin-top: 10px; }
    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; margin-right: 5px; border-radius: 3px; font-size: 0.85em; }
    .content { margin-top: 20px; }
    a { color: #0066cc; }
    code { background: #f5f5f5; padding: 2px 4px; border-radius: 3px; }
    pre { background: #f5f5f5; padding: 10px; border-radius: 3px; overflow-x: auto; }
    .back-link { margin-top: 30px; padding-top: 20px; border-top: 1px solid #eee; }
  </style>
</head>
<body>
  <article>
    <h1>${escapeHtml(page.title)}</h1>
    <div class="meta">
      ${dateHtml}
      ${tagsList}
    </div>
    <div class="content">
      ${page.html}
    </div>
  </article>
  <footer class="back-link">
    <a href="index.html">← Back to all pages</a>
  </footer>
</body>
</html>`;
}

function createIndexHtml(pages: PageData[]): string {
  const pagesList = pages
    .sort((a, b) => {
      if (!a.date || !b.date) return 0;
      return new Date(b.date).getTime() - new Date(a.date).getTime();
    })
    .map(page => `
    <li>
      <a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a>
      ${page.date ? `<span class="date"> — ${escapeHtml(page.date)}</span>` : ''}
      ${page.tags && Array.isArray(page.tags) ? `<div class="tags">${page.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join('')}</div>` : ''}
    </li>
  `).join('');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>All Pages</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; line-height: 1.6; color: #333; }
    h1 { color: #000; }
    ul { list-style: none; padding: 0; }
    li { padding: 10px 0; border-bottom: 1px solid #eee; }
    li:last-child { border-bottom: none; }
    a { color: #0066cc; text-decoration: none; font-weight: 500; }
    a:hover { text-decoration: underline; }
    .date { color: #666; font-size: 0.9em; margin-left: 10px; }
    .tags { margin-top: 5px; display: flex; flex-wrap: wrap; gap: 5px; }
    .tag { display: inline-block; background: #f0f0f0; padding: 4px 8px; border-radius: 3px; font-size: 0.85em; color: #666; }
  </style>
</head>
<body>
  <h1>All Pages</h1>
  <p>Total: ${pages.length} page${pages.length === 1 ? '' : 's'}</p>
  <ul>
    ${pagesList}
  </ul>
</body>
</html>`;
}

function escapeHtml(text: string): string {
  const map: { [key: string]: string } = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  };
  return text.replace(/[&<>"']/g, char => map[char]);
}

#!/usr/bin/env node

import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';
import path from 'path';
import { readMarkdownFiles } from './files';
import { processMarkdownFile } from './page';
import { generatePageHtml, generateIndexHtml } from './generator';

async function build(contentDir: string, outputDir: string): Promise<void> {
  console.log(`Reading markdown files from: ${contentDir}`);
  const files = await readMarkdownFiles(contentDir);

  if (files.length === 0) {
    console.log('No markdown files found.');
    return;
  }

  console.log(`Found ${files.length} markdown file(s).`);

  const pages = [];
  for (const file of files) {
    const page = await processMarkdownFile(file.name, file.content);
    pages.push(page);
    await generatePageHtml(page, outputDir);
    console.log(`✓ Generated ${page.slug}.html`);
  }

  await generateIndexHtml(pages, outputDir);
  console.log(`✓ Generated index.html`);

  console.log(`\nBuild complete! Output: ${outputDir}`);
}

yargs(hideBin(process.argv))
  .command(
    'build',
    'Build the static site',
    (yargs) => {
      return yargs
        .option('content', {
          alias: 'c',
          describe: 'Content directory',
          type: 'string',
          default: './content'
        })
        .option('output', {
          alias: 'o',
          describe: 'Output directory',
          type: 'string',
          default: './dist'
        });
    },
    async (argv) => {
      const contentDir = path.resolve(argv.content as string);
      const outputDir = path.resolve(argv.output as string);

      try {
        await build(contentDir, outputDir);
      } catch (error) {
        console.error('Error:', (error as Error).message);
        process.exit(1);
      }
    }
  )
  .demandCommand()
  .strict()
  .help()
  .parse();

import { parseFrontmatter } from './frontmatter';

describe('parseFrontmatter', () => {
  it('should parse YAML frontmatter', () => {
    const content = `---
title: My Post
date: 2024-01-15
---
# Content here`;

    const result = parseFrontmatter(content);

    expect(result.data.title).toBe('My Post');
    expect(result.data.date).toBe('2024-01-15');
    expect(result.content).toBe('# Content here');
  });

  it('should handle tags as array', () => {
    const content = `---
title: Test
tags: [javascript, typescript, testing]
---
Content`;

    const result = parseFrontmatter(content);

    expect(Array.isArray(result.data.tags)).toBe(true);
    expect(result.data.tags).toEqual(['javascript', 'typescript', 'testing']);
  });

  it('should handle quoted strings', () => {
    const content = `---
title: "My Title with Spaces"
author: 'John Doe'
---
Content`;

    const result = parseFrontmatter(content);

    expect(result.data.title).toBe('My Title with Spaces');
    expect(result.data.author).toBe('John Doe');
  });

  it('should handle boolean values', () => {
    const content = `---
published: true
draft: false
---
Content`;

    const result = parseFrontmatter(content);

    expect(result.data.published).toBe(true);
    expect(result.data.draft).toBe(false);
  });

  it('should handle missing frontmatter', () => {
    const content = '# No frontmatter\nJust content';

    const result = parseFrontmatter(content);

    expect(result.data).toEqual({});
    expect(result.content).toBe('# No frontmatter\nJust content');
  });

  it('should handle unclosed frontmatter', () => {
    const content = `---
title: Unclosed
# No closing delimiter
Content`;

    const result = parseFrontmatter(content);

    expect(result.data).toEqual({});
    expect(result.content).toBe(content);
  });

  it('should handle empty frontmatter', () => {
    const content = `---
---
Content here`;

    const result = parseFrontmatter(content);

    expect(result.data).toEqual({});
    expect(result.content).toBe('Content here');
  });

  it('should skip comment lines in frontmatter', () => {
    const content = `---
title: My Post
# This is a comment
date: 2024-01-15
---
Content`;

    const result = parseFrontmatter(content);

    expect(result.data.title).toBe('My Post');
    expect(result.data.date).toBe('2024-01-15');
  });

  it('should handle whitespace-only lines', () => {
    const content = `---
title: Test

date: 2024-01-15
---
Content`;

    const result = parseFrontmatter(content);

    expect(result.data.title).toBe('Test');
    expect(result.data.date).toBe('2024-01-15');
  });
});

import { markdownToHtml } from './markdown';

describe('markdownToHtml', () => {
  it('should convert markdown to HTML', async () => {
    const markdown = '# Hello World';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<h1>Hello World</h1>');
  });

  it('should handle paragraphs', async () => {
    const markdown = 'This is a paragraph.\n\nThis is another paragraph.';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<p>This is a paragraph.</p>');
    expect(html).toContain('<p>This is another paragraph.</p>');
  });

  it('should handle bold and italic', async () => {
    const markdown = '**bold** and *italic*';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<em>italic</em>');
  });

  it('should handle lists', async () => {
    const markdown = '- Item 1\n- Item 2\n- Item 3';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<ul>');
    expect(html).toContain('<li>Item 1</li>');
    expect(html).toContain('<li>Item 2</li>');
    expect(html).toContain('<li>Item 3</li>');
    expect(html).toContain('</ul>');
  });

  it('should handle code blocks', async () => {
    const markdown = '```javascript\nconst x = 1;\n```';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<code>');
  });

  it('should handle inline code', async () => {
    const markdown = 'This is `inline code` in text.';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<code>inline code</code>');
  });

  it('should handle links', async () => {
    const markdown = '[Example](https://example.com)';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<a href="https://example.com">Example</a>');
  });

  it('should handle headings', async () => {
    const markdown = '# H1\n## H2\n### H3';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<h1>H1</h1>');
    expect(html).toContain('<h2>H2</h2>');
    expect(html).toContain('<h3>H3</h3>');
  });

  it('should handle empty content', async () => {
    const markdown = '';
    const html = await markdownToHtml(markdown);

    expect(typeof html).toBe('string');
  });

  it('should handle blockquotes', async () => {
    const markdown = '> This is a quote';
    const html = await markdownToHtml(markdown);

    expect(html).toContain('<blockquote>');
  });
});

import { promises as fs } from 'fs';
import path from 'path';
import { readMarkdownFiles, writeFile, ensureDir } from './files';

const testDir = path.join(__dirname, '..', '__test_temp__');

async function cleanup(): Promise<void> {
  try {
    await fs.rm(testDir, { recursive: true, force: true });
  } catch (e) {
    // ignored
  }
}

describe('files', () => {
  beforeEach(async () => {
    await cleanup();
  });

  afterEach(async () => {
    await cleanup();
  });

  describe('readMarkdownFiles', () => {
    it('should read markdown files from directory', async () => {
      const contentDir = path.join(testDir, 'content');
      await fs.mkdir(contentDir, { recursive: true });

      await fs.writeFile(path.join(contentDir, 'post1.md'), '# Post 1');
      await fs.writeFile(path.join(contentDir, 'post2.md'), '# Post 2');
      await fs.writeFile(path.join(contentDir, 'other.txt'), 'Not markdown');

      const files = await readMarkdownFiles(contentDir);

      expect(files).toHaveLength(2);
      expect(files.map(f => f.name).sort()).toEqual(['post1.md', 'post2.md']);
      expect(files[0].content).toBeDefined();
    });

    it('should create directory if it does not exist', async () => {
      const contentDir = path.join(testDir, 'nonexistent');

      const files = await readMarkdownFiles(contentDir);

      expect(files).toHaveLength(0);

      const exists = await fs.stat(contentDir).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should handle empty directory', async () => {
      const contentDir = path.join(testDir, 'empty');
      await fs.mkdir(contentDir, { recursive: true });

      const files = await readMarkdownFiles(contentDir);

      expect(files).toHaveLength(0);
    });

    it('should ignore non-markdown files', async () => {
      const contentDir = path.join(testDir, 'content');
      await fs.mkdir(contentDir, { recursive: true });

      await fs.writeFile(path.join(contentDir, 'post.md'), '# Post');
      await fs.writeFile(path.join(contentDir, 'image.png'), 'fake image');
      await fs.writeFile(path.join(contentDir, 'doc.txt'), 'text file');

      const files = await readMarkdownFiles(contentDir);

      expect(files).toHaveLength(1);
      expect(files[0].name).toBe('post.md');
    });
  });

  describe('writeFile', () => {
    it('should write file to disk', async () => {
      const filePath = path.join(testDir, 'output', 'test.html');
      const content = '<html>test</html>';

      await writeFile(filePath, content);

      const written = await fs.readFile(filePath, 'utf-8');
      expect(written).toBe(content);
    });

    it('should create directories if they do not exist', async () => {
      const filePath = path.join(testDir, 'deep', 'nested', 'path', 'file.html');

      await writeFile(filePath, '<html>test</html>');

      const exists = await fs.stat(filePath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should overwrite existing files', async () => {
      const filePath = path.join(testDir, 'file.txt');
      await fs.mkdir(path.dirname(filePath), { recursive: true });
      await fs.writeFile(filePath, 'old content');

      await writeFile(filePath, 'new content');

      const content = await fs.readFile(filePath, 'utf-8');
      expect(content).toBe('new content');
    });
  });

  describe('ensureDir', () => {
    it('should create directory', async () => {
      const dirPath = path.join(testDir, 'mydir');

      await ensureDir(dirPath);

      const exists = await fs.stat(dirPath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should handle existing directory', async () => {
      const dirPath = path.join(testDir, 'existing');
      await fs.mkdir(dirPath, { recursive: true });

      await ensureDir(dirPath);

      const exists = await fs.stat(dirPath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should create nested directories', async () => {
      const dirPath = path.join(testDir, 'nested', 'deep', 'path');

      await ensureDir(dirPath);

      const exists = await fs.stat(dirPath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });
  });
});

import { processMarkdownFile } from './page';

describe('processMarkdownFile', () => {
  it('should extract title from frontmatter', async () => {
    const content = `---
title: My First Post
---
# Content`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.title).toBe('My First Post');
  });

  it('should generate title from slug if not in frontmatter', async () => {
    const content = '# Content';

    const page = await processMarkdownFile('my-first-post.md', content);

    expect(page.title).toBe('My First Post');
  });

  it('should extract date from frontmatter', async () => {
    const content = `---
title: Post
date: 2024-01-15
---
Content`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.date).toBe('2024-01-15');
  });

  it('should extract tags from frontmatter', async () => {
    const content = `---
title: Post
tags: [javascript, testing, cli]
---
Content`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.tags).toEqual(['javascript', 'testing', 'cli']);
  });

  it('should convert markdown to HTML', async () => {
    const content = `---
title: Post
---
# Heading

This is **bold** text.`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.html).toContain('<h1>Heading</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
  });

  it('should set slug from filename', async () => {
    const content = 'Content';

    const page = await processMarkdownFile('my-post.md', content);

    expect(page.slug).toBe('my-post');
  });

  it('should handle no tags', async () => {
    const content = `---
title: Post
---
Content`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.tags).toBeUndefined();
  });

  it('should preserve additional frontmatter fields', async () => {
    const content = `---
title: Post
author: John Doe
category: Tech
---
Content`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.author).toBe('John Doe');
    expect(page.category).toBe('Tech');
  });

  it('should handle complex markdown', async () => {
    const content = `---
title: Complex
---
# Header

- List item 1
- List item 2

\`\`\`javascript
const x = 1;
\`\`\`

[Link](https://example.com)`;

    const page = await processMarkdownFile('test.md', content);

    expect(page.html).toContain('<ul>');
    expect(page.html).toContain('List item 1');
    expect(page.html).toContain('<a href="https://example.com">Link</a>');
  });

  it('should handle empty frontmatter', async () => {
    const content = `---
---
# Default Title
Content`;

    const page = await processMarkdownFile('some-title.md', content);

    expect(page.title).toBe('Some Title');
    expect(page.slug).toBe('some-title');
  });
});

import { promises as fs } from 'fs';
import path from 'path';
import { generatePageHtml, generateIndexHtml } from './generator';
import { PageData } from './page';

const testDir = path.join(__dirname, '..', '__test_gen__');

async function cleanup(): Promise<void> {
  try {
    await fs.rm(testDir, { recursive: true, force: true });
  } catch (e) {
    // ignored
  }
}

describe('generator', () => {
  beforeEach(async () => {
    await cleanup();
  });

  afterEach(async () => {
    await cleanup();
  });

  describe('generatePageHtml', () => {
    it('should generate page HTML file', async () => {
      const page: PageData = {
        slug: 'test-post',
        title: 'Test Post',
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const filePath = path.join(testDir, 'test-post.html');
      const exists = await fs.stat(filePath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should include title in page HTML', async () => {
      const page: PageData = {
        slug: 'test',
        title: 'My Page Title',
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).toContain('My Page Title');
      expect(content).toContain('<h1>My Page Title</h1>');
    });

    it('should include page content in HTML', async () => {
      const page: PageData = {
        slug: 'test',
        title: 'Test',
        html: '<p>This is the page content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).toContain('This is the page content');
    });

    it('should include date if provided', async () => {
      const page: PageData = {
        slug: 'test',
        title: 'Test',
        date: '2024-01-15',
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).toContain('2024-01-15');
    });

    it('should include tags if provided', async () => {
      const page: PageData = {
        slug: 'test',
        title: 'Test',
        tags: ['javascript', 'tutorial'],
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).toContain('javascript');
      expect(content).toContain('tutorial');
      expect(content).toContain('class="tag"');
    });

    it('should include back link to index', async () => {
      const page: PageData = {
        slug: 'test',
        title: 'Test',
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).toContain('index.html');
      expect(content).toContain('Back to all pages');
    });

    it('should escape HTML in title', async () => {
      const page: PageData = {
        slug: 'test',
        title: '<script>alert("xss")</script>',
        html: '<p>Content</p>'
      };

      await generatePageHtml(page, testDir);

      const content = await fs.readFile(path.join(testDir, 'test.html'), 'utf-8');
      expect(content).not.toContain('<script>');
      expect(content).toContain('&lt;script&gt;');
    });
  });

  describe('generateIndexHtml', () => {
    it('should generate index HTML file', async () => {
      const pages: PageData[] = [
        {
          slug: 'post1',
          title: 'Post 1',
          html: '<p>Content</p>'
        }
      ];

      await generateIndexHtml(pages, testDir);

      const filePath = path.join(testDir, 'index.html');
      const exists = await fs.stat(filePath).then(() => true).catch(() => false);
      expect(exists).toBe(true);
    });

    it('should list all pages in index', async () => {
      const pages: PageData[] = [
        { slug: 'post1', title: 'First Post', html: '<p>Content</p>' },
        { slug: 'post2', title: 'Second Post', html: '<p>Content</p>' }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('First Post');
      expect(content).toContain('Second Post');
      expect(content).toContain('post1.html');
      expect(content).toContain('post2.html');
    });

    it('should show page count', async () => {
      const pages: PageData[] = [
        { slug: 'post1', title: 'Post 1', html: '<p>Content</p>' },
        { slug: 'post2', title: 'Post 2', html: '<p>Content</p>' }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('Total: 2 pages');
    });

    it('should sort pages by date descending', async () => {
      const pages: PageData[] = [
        { slug: 'post1', title: 'First', date: '2024-01-10', html: '<p>1</p>' },
        { slug: 'post2', title: 'Third', date: '2024-01-20', html: '<p>3</p>' },
        { slug: 'post3', title: 'Second', date: '2024-01-15', html: '<p>2</p>' }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      const post2Index = content.indexOf('Third');
      const post3Index = content.indexOf('Second');
      const post1Index = content.indexOf('First');

      expect(post2Index).toBeLessThan(post3Index);
      expect(post3Index).toBeLessThan(post1Index);
    });

    it('should include dates in index', async () => {
      const pages: PageData[] = [
        { slug: 'post1', title: 'Post', date: '2024-01-15', html: '<p>Content</p>' }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('2024-01-15');
    });

    it('should include tags in index', async () => {
      const pages: PageData[] = [
        {
          slug: 'post1',
          title: 'Post',
          tags: ['javascript', 'web'],
          html: '<p>Content</p>'
        }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('javascript');
      expect(content).toContain('web');
    });

    it('should escape HTML in titles', async () => {
      const pages: PageData[] = [
        {
          slug: 'test',
          title: '<script>alert("xss")</script>',
          html: '<p>Content</p>'
        }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).not.toContain('<script>');
      expect(content).toContain('&lt;script&gt;');
    });

    it('should handle empty pages array', async () => {
      await generateIndexHtml([], testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('Total: 0 pages');
    });

    it('should handle single page correctly', async () => {
      const pages: PageData[] = [
        { slug: 'post', title: 'Post', html: '<p>Content</p>' }
      ];

      await generateIndexHtml(pages, testDir);

      const content = await fs.readFile(path.join(testDir, 'index.html'), 'utf-8');
      expect(content).toContain('Total: 1 page');
    });
  });
});

